<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch} from 'vue';
import {api,can,type Configuration,type AlarmOccurrence} from './api';
import {qualityNames,converted,unit,type Quantity} from './units';
const props=defineProps<{licensed:boolean;config:Configuration;canOperate:boolean}>();
const records=ref<AlarmOccurrence[]>([]),selected=ref<string[]>([]),error=ref(''),message=ref(''),busy=ref(false),state=ref('attention'),tank=ref('all'),start=ref(''),end=ref('');
let timer:ReturnType<typeof setInterval>|undefined,applied='state=attention';
const states:Record<string,string>={ActiveUnacknowledged:'活动 · 待确认',ActiveAcknowledged:'活动 · 已确认',RecoveredUnacknowledged:'已恢复 · 待确认',Closed:'已恢复 · 已确认',Ended:'监测已终止'};
function date(value:string|null){return value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—'}
function quantity(a:AlarmOccurrence):Quantity|null{const mapping:Record<string,Quantity>={Level:'level',Temperature:'temperature',Density:'density'};return mapping[a.rule.quantity]||null}
function value(a:AlarmOccurrence,v:number|null){if(v===null)return '—';const q=quantity(a);if(q)return converted(v,q,props.config.display).toLocaleString('zh-CN',{maximumFractionDigits:4})+' '+unit(q,props.config.display);if(a.rule.quantity==='Pressure1'||a.rule.quantity==='Pressure2')return v.toLocaleString('zh-CN',{maximumFractionDigits:3})+' kPa';return String(v)}
async function load(apply=false){if(busy.value)return;busy.value=true;try{if(apply){const q=new URLSearchParams({state:state.value});if(tank.value!=='all')q.set('tank',tank.value);if(start.value)q.set('start',new Date(start.value).toISOString());if(end.value)q.set('end',new Date(end.value).toISOString());applied=q.toString()}const query=applied;const data=await api<{records:AlarmOccurrence[];error:string}>('/api/alarms?'+query);if(!props.licensed&&new URLSearchParams(query).get('state')?.match(/^(all|history)$/))return;records.value=data.records;error.value=data.error;selected.value=selected.value.filter(id=>records.value.some(a=>a.id===id&&!a.acknowledgedAtUtc&&!a.endedAtUtc))}catch(e){error.value=String(e)}finally{busy.value=false}}
async function acknowledge(ids:string[]){if(!ids.length||busy.value)return;busy.value=true;try{const r=await api<{acknowledged:number}>('/api/alarms/acknowledge','POST',{ids});message.value='已确认 '+r.acknowledged+' 条报警。活动报警仍保留到有效读数恢复。';selected.value=[];error.value=''}catch(e){error.value=String(e)}finally{busy.value=false}await load()}
function exportRows(){if(!props.licensed)return;window.LocalWorkbook.download('报警查询结果',[{name:'报警记录',rows:[['储罐','报警','级别','发生时间','当时值','限值','状态','最新数据质量','恢复时间','恢复值','确认时间','确认人','终止原因'],...records.value.map(a=>[a.rule.tankCode,a.rule.name,a.rule.severity==='Important'?'重要':'一般',date(a.activatedAtUtc),value(a,a.triggerValue),value(a,a.rule.threshold),states[a.state],qualityNames[a.lastQuality],date(a.restoredAtUtc),value(a,a.restoreValue),date(a.acknowledgedAtUtc),a.acknowledgedByName||'',a.endReason||''])]}])}
watch(()=>props.licensed,allowed=>{if(!allowed&&['all','history'].includes(state.value)){state.value='attention';applied='state=attention';records.value=[];selected.value=[];void load(true)}});
onMounted(()=>{void load();timer=setInterval(()=>void load(),2000)});onUnmounted(()=>{if(timer)clearInterval(timer)});
</script>
<template><div class="notice">报警确认表示已知悉，不能代替实际恢复。无效或过期读数不会自动清除原有报警；隐藏储罐仍参与报警监测。</div><div v-if="error" class="notice error-message" role="alert">{{error}}</div><div v-if="message" class="notice success-message" role="status">{{message}}</div><form class="panel query-panel" @submit.prevent="load(true)"><div class="query-fields"><label class="config-field">报警范围<select v-model="state" aria-label="报警范围"><option value="attention">活动及恢复待确认</option><option value="active">活动报警</option><option value="unacknowledged">待确认报警</option><option value="history" :disabled="!licensed||!can('HistoryRead')">已结束记录</option><option value="all" :disabled="!licensed||!can('HistoryRead')">全部记录</option></select></label><label class="config-field">储罐<select v-model="tank" aria-label="报警储罐"><option value="all">全部储罐（含隐藏罐）</option><option v-for="t in config.tanks" :key="t.id" :value="t.id">{{t.code}}{{t.hidden?' · 隐藏':''}}</option></select></label><label class="config-field">开始时间<input v-model="start" type="datetime-local"></label><label class="config-field">结束时间<input v-model="end" type="datetime-local"></label></div><button class="button primary" :disabled="busy">查询</button></form><section class="panel"><div class="toolbar"><span>查询最多500条 · 时间为软件检测时间</span><div><button v-if="canOperate" class="button primary" :disabled="!selected.length||busy" @click="acknowledge(selected)">确认所选 {{selected.length||''}}</button><button class="button" :disabled="!licensed||!can('DataExport')||!records.length" :data-export-allowed="can('DataExport')" @click="can('DataExport')&&exportRows()">导出当前结果</button></div></div><div class="table-wrap"><table><thead><tr><th>选择</th><th>发生时间 / 储罐</th><th>报警内容</th><th>发生值 / 限值</th><th>状态</th><th>恢复时间 / 恢复值</th><th>确认时间 / 人员</th><th>操作</th></tr></thead><tbody><tr v-for="a in records" :key="a.id" :class="{'alarm-active-row':a.active,'alarm-recovered-row':a.state==='RecoveredUnacknowledged'}"><td><input v-if="canOperate&&!a.acknowledgedAtUtc&&!a.endedAtUtc" v-model="selected" type="checkbox" :value="a.id" :aria-label="'选择 '+a.rule.tankCode+' '+a.rule.name"></td><td>{{date(a.activatedAtUtc)}}<small>{{a.rule.tankCode}}</small></td><td>{{a.rule.name}}<small>{{a.rule.severity==='Important'?'重要':'一般'}}</small></td><td>{{value(a,a.triggerValue)}}<small>限值 {{value(a,a.rule.threshold)}}</small></td><td><strong>{{states[a.state]}}</strong><small v-if="a.active&&a.lastQuality!=='Good'">{{qualityNames[a.lastQuality]}} · 原报警保留</small><small v-if="a.endReason">{{a.endReason}}</small></td><td>{{date(a.restoredAtUtc)}}<small>{{value(a,a.restoreValue)}}</small></td><td>{{date(a.acknowledgedAtUtc)}}<small>{{a.acknowledgedByName||'—'}}</small></td><td><button v-if="canOperate&&!a.acknowledgedAtUtc&&!a.endedAtUtc" class="text-button" :disabled="busy" @click="acknowledge([a.id])">确认</button></td></tr><tr v-if="!records.length"><td colspan="8" class="empty">暂无符合条件的报警</td></tr></tbody></table></div></section></template>
